CREATE TABLE public.financial_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, provider text NOT NULL, institution_id text NOT NULL, institution_name text NOT NULL, institution_logo text, external_connection_id text, environment text NOT NULL CHECK(environment IN ('sandbox','production')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','expired','error','disconnected')), connected_at timestamptz,last_sync_at timestamptz,expires_at timestamptz,authorization_hash text,authorization_expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,user_id));
GRANT SELECT ON public.financial_connections TO authenticated; GRANT ALL ON public.financial_connections TO service_role;
ALTER TABLE public.financial_connections ENABLE ROW LEVEL SECURITY; CREATE POLICY own_connections ON public.financial_connections FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE UNIQUE INDEX one_live_financial_connection ON public.financial_connections(user_id,provider,institution_id,environment) WHERE status<>'disconnected';
CREATE TABLE public.open_finance_consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,connection_id uuid NOT NULL,purpose text NOT NULL,scopes text[] NOT NULL,recipient text NOT NULL DEFAULT 'Finlux Finance (Sandbox)',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','expired','revoked','error')),authorized_at timestamptz,expires_at timestamptz NOT NULL,revoked_at timestamptz,policy_version text NOT NULL DEFAULT '2026-11-02',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(connection_id,user_id) REFERENCES public.financial_connections(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.open_finance_consents TO authenticated; GRANT ALL ON public.open_finance_consents TO service_role;
ALTER TABLE public.open_finance_consents ENABLE ROW LEVEL SECURITY; CREATE POLICY own_consents ON public.open_finance_consents FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.financial_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,connection_id uuid NOT NULL,external_id text NOT NULL,name text NOT NULL,type text NOT NULL,currency text NOT NULL DEFAULT 'BRL',balance numeric(18,2) NOT NULL DEFAULT 0,included boolean NOT NULL DEFAULT false,balance_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,external_id),UNIQUE(id,user_id),FOREIGN KEY(connection_id,user_id) REFERENCES public.financial_connections(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.financial_accounts TO authenticated; GRANT ALL ON public.financial_accounts TO service_role;
ALTER TABLE public.financial_accounts ENABLE ROW LEVEL SECURITY; CREATE POLICY own_accounts ON public.financial_accounts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.credit_cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,connection_id uuid NOT NULL,external_id text NOT NULL,name text NOT NULL,brand text NOT NULL,total_limit numeric(18,2) NOT NULL,available_limit numeric(18,2) NOT NULL,used_limit numeric(18,2) NOT NULL,included boolean NOT NULL DEFAULT false,due_date date,closing_date date,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,external_id),UNIQUE(id,user_id),FOREIGN KEY(connection_id,user_id) REFERENCES public.financial_connections(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.credit_cards TO authenticated; GRANT ALL ON public.credit_cards TO service_role;
ALTER TABLE public.credit_cards ENABLE ROW LEVEL SECURITY; CREATE POLICY own_of_cards ON public.credit_cards FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.credit_card_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,connection_id uuid NOT NULL,card_id uuid NOT NULL,external_id text NOT NULL,total numeric(18,2) NOT NULL,paid numeric(18,2) NOT NULL DEFAULT 0,due_date date NOT NULL,closing_date date NOT NULL,status text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,external_id),UNIQUE(id,user_id),FOREIGN KEY(connection_id,user_id) REFERENCES public.financial_connections(id,user_id) ON DELETE CASCADE,FOREIGN KEY(card_id,user_id) REFERENCES public.credit_cards(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.credit_card_invoices TO authenticated; GRANT ALL ON public.credit_card_invoices TO service_role;
ALTER TABLE public.credit_card_invoices ENABLE ROW LEVEL SECURITY; CREATE POLICY own_invoices ON public.credit_card_invoices FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.financial_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,connection_id uuid NOT NULL,account_id uuid NOT NULL,external_id text NOT NULL,date timestamptz NOT NULL,description text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),kind text NOT NULL CHECK(kind IN ('receita','despesa','transferencia')),category text NOT NULL,status text NOT NULL DEFAULT 'posted',source text NOT NULL DEFAULT 'open_finance' CHECK(source='open_finance'),review_status text NOT NULL DEFAULT 'accepted' CHECK(review_status IN ('accepted','possible_duplicate','ignored')),matched_transaction_id uuid,manually_categorized boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,account_id,external_id),FOREIGN KEY(connection_id,user_id) REFERENCES public.financial_connections(id,user_id) ON DELETE CASCADE,FOREIGN KEY(account_id,user_id) REFERENCES public.financial_accounts(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.financial_transactions TO authenticated; GRANT ALL ON public.financial_transactions TO service_role;
ALTER TABLE public.financial_transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY own_financial_transactions ON public.financial_transactions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.credit_card_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,connection_id uuid NOT NULL,card_id uuid NOT NULL,invoice_id uuid,external_id text NOT NULL,date timestamptz NOT NULL,description text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),category text NOT NULL,installments integer NOT NULL DEFAULT 1,installment_number integer NOT NULL DEFAULT 1,invoice_paid boolean NOT NULL DEFAULT false,review_status text NOT NULL DEFAULT 'accepted' CHECK(review_status IN ('accepted','possible_duplicate','ignored')),matched_transaction_id uuid,manually_categorized boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,card_id,external_id),FOREIGN KEY(connection_id,user_id) REFERENCES public.financial_connections(id,user_id) ON DELETE CASCADE,FOREIGN KEY(card_id,user_id) REFERENCES public.credit_cards(id,user_id) ON DELETE CASCADE,FOREIGN KEY(invoice_id,user_id) REFERENCES public.credit_card_invoices(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.credit_card_transactions TO authenticated; GRANT ALL ON public.credit_card_transactions TO service_role;
ALTER TABLE public.credit_card_transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY own_card_transactions ON public.credit_card_transactions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.sync_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,connection_id uuid,event text NOT NULL CHECK(event IN ('connection_started','connection_authorized','connection_failed','sync_started','sync_completed','sync_failed','connection_refreshed','connection_disconnected','consent_created','consent_revoked')),result text NOT NULL DEFAULT 'ok',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(connection_id,user_id) REFERENCES public.financial_connections(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.sync_logs TO authenticated; GRANT ALL ON public.sync_logs TO service_role;
ALTER TABLE public.sync_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY own_sync_logs ON public.sync_logs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX of_transactions_user_date ON public.financial_transactions(user_id,date DESC); CREATE INDEX of_card_transactions_user_date ON public.credit_card_transactions(user_id,date DESC); CREATE INDEX of_logs_user_date ON public.sync_logs(user_id,created_at DESC);
ALTER TABLE public.transactions ADD COLUMN source text NOT NULL DEFAULT 'manual'; ALTER TABLE public.transactions ADD COLUMN financial_account_id uuid; ALTER TABLE public.transactions ADD COLUMN financial_institution_id text; ALTER TABLE public.transactions ADD COLUMN reconciled_open_finance_id uuid;